package cmd

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/gonvenience/bunt"
	"github.com/gonvenience/text"
	"github.com/gonvenience/ytbx"
	"github.com/homeport/dyff/pkg/dyff"
	"github.com/lucasb-eyer/go-colorful"
	"github.com/spf13/cobra"
)

type DiffCmdArgs struct {
	File        string
	Environment string
}

var diffCmdArgs DiffCmdArgs

var DiffCmd = setupDiffCmd()

type DiffResult struct {
	Diffs      []dyff.Diff
	FilePath   string
	Successful bool
}

// Function to save the main branch content to a temp file and return a path to it.
type storeCompareTargetToTemp func(string, string) (string, error)

// setupDiffCmd returns a cobra command that diffs kustomize resources against same resources on main branch.
func setupDiffCmd() *cobra.Command {
	diffCmd := &cobra.Command{
		Use: "diff",
		Example: "diff" +
			"\ndiff -f path/to/file.yaml" +
			"\ndiff -e default,production",
		Short: "Diff kubernetes configuration files generated by kustomize against the same files on main branch",
		RunE: func(cmd *cobra.Command, args []string) error {
			return getDiffCmd()(cmd, args, saveMainBranchContentToTempFile)
		},
		SilenceUsage: true,
	}

	diffCmd.Flags().StringVarP(
		&diffCmdArgs.Environment,
		"environment",
		"e",
		"",
		"name of environment to diff",
	)

	diffCmd.Flags().StringVarP(
		&diffCmdArgs.File,
		"file",
		"f",
		"",
		"Individual file to diff",
	)

	RootCmd.AddCommand(diffCmd)

	diffCmdArgs = DiffCmdArgs{}
	return diffCmd
}

func getDiffCmd() func(cmd *cobra.Command, args []string, getMainVersionPath storeCompareTargetToTemp) error {
	return func(cmd *cobra.Command, args []string, getMainVersionPath storeCompareTargetToTemp) error {
		gitRoot, err := getGitRootDir()
		if err != nil {
			return errors.New("not a git repository")
		}
		reports, err := execute(cmd, gitRoot, getMainVersionPath)
		if err != nil {
			return err
		}
		return printReports(cmd, reports)
	}
}

func execute(cmd *cobra.Command, gitRoot string, getMainVersionPath storeCompareTargetToTemp) (diffResults []DiffResult, err error) {
	if diffCmdArgs.File != "" && diffCmdArgs.Environment != "" {
		return diffResults, errors.New("cannot specify both file and environment")
	}
	tempDir, err := os.MkdirTemp("", "kustomizetemp")
	if err != nil {
		return diffResults, err
	}
	defer os.RemoveAll(tempDir)

	switch diffCmdArgs {
	case DiffCmdArgs{}:
		printMainHeader(cmd, "all files in environment "+gitRoot)
		return diffProject(cmd, gitRoot, tempDir, getMainVersionPath)

	case DiffCmdArgs{File: diffCmdArgs.File}:
		printMainHeader(cmd, "file: "+diffCmdArgs.File)
		diffResult, err := singleDiff(diffCmdArgs.File, gitRoot, tempDir, getMainVersionPath)
		if err != nil {
			return diffResults, err
		}
		diffResults = append(diffResults, diffResult)
		return diffResults, nil

	case DiffCmdArgs{Environment: diffCmdArgs.Environment}:
		printMainHeader(cmd, "all files in folder "+gitRoot)
		return diffDeployTarget(cmd, diffCmdArgs.Environment, gitRoot, tempDir, getMainVersionPath)

	default:
		return diffResults, errors.New("invalid arguments")
	}
}

func getGitRootDir() (string, error) {
	out, err := exec.Command("git", "rev-parse", "--show-toplevel").Output()
	if err != nil {
		return "", fmt.Errorf("no git directory found at path: %w", err)
	}
	return strings.TrimSuffix(string(out), "\n"), err
}

func diffProject(cmd *cobra.Command, gitRoot, tempDir string, getMainVersionPath storeCompareTargetToTemp) (diffResults []DiffResult, err error) {
	configPath := filepath.Join(gitRoot, "config", "kubernetes")
	configFolder, err := os.ReadDir(configPath)
	if err != nil {
		return nil, fmt.Errorf("could not read config folder: %w", err)
	}
	for _, folder := range configFolder {
		if folder.IsDir() {
			result, err := diffDeployTarget(cmd, folder.Name(), gitRoot, tempDir, getMainVersionPath)
			if err != nil {
				return nil, err
			}
			diffResults = append(diffResults, result...)
		}
	}

	return diffResults, nil
}

func diffDeployTarget(cmd *cobra.Command, target, gitRoot, tempDir string, getMainVersionPath storeCompareTargetToTemp) (diffResults []DiffResult, err error) {
	targetDirectory := filepath.Join(gitRoot, "config", "kubernetes", target)
	configFiles, err := walkDir(targetDirectory)
	if err != nil {
		return diffResults, fmt.Errorf("error walking directory: %w", err)
	}
	for _, file := range configFiles {
		// skip non yaml files.
		if !strings.HasSuffix(file, ".yaml") && !strings.HasSuffix(file, ".yml") {
			continue
		}

		relativePath := strings.TrimPrefix(file, gitRoot)
		diffResult, err := singleDiff(relativePath, gitRoot, tempDir, getMainVersionPath)
		if err != nil {
			printError(cmd, file, err)
		}

		diffResults = append(diffResults, diffResult)
	}
	return diffResults, nil
}

func walkDir(dir string) (paths []string, err error) {
	err = filepath.WalkDir(dir, func(path string, info os.DirEntry, err error) error {
		if err != nil {
			return fmt.Errorf("failed walking the directory %s with error: %w", dir, err)
		}
		if !info.IsDir() {
			paths = append(paths, path)
		}
		return nil
	})
	return paths, err
}

func singleDiff(filePath, gitRoot, tempDir string, getMainVersionPath storeCompareTargetToTemp) (diffResult DiffResult, err error) {
	fullPath := filepath.Join(gitRoot, filePath)
	if _, err := os.Stat(filepath.Clean(fullPath)); os.IsNotExist(err) {
		return diffResult, fmt.Errorf("file %s does not exist", fullPath)
	}

	tempFile, err := getMainVersionPath(filePath, tempDir)
	if err != nil {
		return diffResult, err
	}
	from, to, err := ytbx.LoadFiles(fullPath, tempFile)
	if err != nil {
		return diffResult, fmt.Errorf("failed to load files: %w", err)
	}
	report, err := dyff.CompareInputFiles(from, to, dyff.IgnoreOrderChanges(true))
	if err != nil {
		return diffResult, fmt.Errorf("failed to compare files: %w", err)
	}
	diffResult = DiffResult{
		FilePath:   filePath,
		Diffs:      report.Diffs,
		Successful: true,
	}
	return diffResult, nil
}

// path has to be relative to the root of the git repo as it will be used to get the main branch content.
func saveMainBranchContentToTempFile(filePath, tempDir string) (tempFile string, err error) {
	filePath = strings.TrimPrefix(filePath, "/")
	tempFilePath := filepath.Join(tempDir, filePath)
	tempFolderPath := filepath.Dir(tempFilePath)
	if _, err := os.Stat(tempFolderPath); os.IsNotExist(err) {
		err = os.MkdirAll(tempFolderPath, os.ModePerm)
		if err != nil {
			return "", fmt.Errorf("failed to create temp folder %s error: %w", tempFolderPath, err)
		}
	}

	command := exec.Command("git", "show", "main:"+filePath)
	file, _ := os.Create(tempFilePath)
	command.Stdout = file

	if err := command.Run(); err != nil {
		// if the repo has not migrated to main branch, load files from master.
		command = exec.Command("git", "show", "master:"+filePath)
		command.Stdout = file
		if err := command.Run(); err != nil {
			return "", fmt.Errorf("file not found on main branch: %s. error: %w", filePath, err)
		}
	}
	return tempFilePath, nil
}

func printMainHeader(cmd *cobra.Command, input string) {
	header := fmt.Sprintf(bunt.Style(`
    Executing DYFF against local main branch content and %s:`, bunt.Foreground(colorful.Color{R: 64, G: 120, B: 192}), bunt.Bold()), input)
	cmd.Println(header)
}

func printFileHeader(cmd *cobra.Command, filePath string, numberOfDiffs int) {
	relativePath := strings.TrimPrefix(filePath, "/")
	header := fmt.Sprintf(`
  dyff between %s		        		    
  and same file on main branch returned %s`,
		relativePath,
		bunt.Style(text.Plural(numberOfDiffs, "difference"), bunt.Bold()))

	cmd.Println(header)
}

func printReports(cmd *cobra.Command, diffResults []DiffResult) error {
	anyDiffs := false
	hasBadFiles := false
	for _, diffResult := range diffResults {
		if len(diffResult.Diffs) == 0 {
			continue
		}
		anyDiffs = true
		reporter := dyff.HumanReport{
			Report: dyff.Report{
				Diffs: diffResult.Diffs,
			},
			DoNotInspectCerts: false,
			NoTableStyle:      false,
			OmitHeader:        true,
		}
		relativePath := strings.TrimPrefix(diffResult.FilePath, "/")
		printFileHeader(cmd, relativePath, len(diffResult.Diffs))

		var buf bytes.Buffer
		if err := reporter.WriteReport(&buf); err != nil {
			cmd.Println(err.Error())
		}
		cmd.Println(buf.String())
		if !diffResult.Successful {
			hasBadFiles = true
		}

	}
	if !anyDiffs && !hasBadFiles {
		printNoDifferences(cmd)
	}
	return nil
}

func printError(cmd *cobra.Command, file string, err error) {
	message := fmt.Sprintf(`
  dyff between %s		        		    
  and same file on main branch returned error: %s`,
		bunt.Style(file, bunt.Bold()),
		err)
	cmd.Println(
		bunt.Style(message, bunt.Foreground(colorful.Color{R: .65, G: .17, B: .17})))
}

func printNoDifferences(cmd *cobra.Command) {
	cmd.Println(
		bunt.Style("    No differences found!", bunt.Foreground(colorful.Color{R: .45, G: .71, B: .30}), bunt.Bold()))
}
